-- IPA 2021-06-13 security and software development questions, source reviewed.
INSERT OR IGNORE INTO questions (id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language,exam_section,exam_section_method,question_kind,exam_origin) VALUES
('fe-exempt-2021-20210613-q42','exam-fe','シャドーIT','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問42・改編】業務利用に情報システム部門の許可が必要なのに、許可を得ずに利用されるデバイス、クラウドサービス、ソフトウェアを指す用語はどれか。','[{"id":"a","text":"シャドーIT"},{"id":"b","text":"ソーシャルエンジニアリング"},{"id":"c","text":"ダークネット"},{"id":"d","text":"バックドア"}]','"a"','シャドーITは組織の許可や管理を経ずに業務で使用されるITを指す。 中文：影子IT是未经过组织许可或管理而用于工作的设备和服务。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q43','exam-fe','二要素認証','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問43・改編】二要素認証に該当するものはどれか。','[{"id":"a","text":"2本の指の指紋で認証する"},{"id":"b","text":"虹彩とパスワードで認証する"},{"id":"c","text":"2種類の特殊文字を混ぜたパスワードで認証する"},{"id":"d","text":"異なる二つのパスワードで認証する"}]','"b"','虹彩は生体情報、パスワードは知識情報で、異なる二種類の要素を使う。 中文：虹膜属于生物特征，密码属于知识因素；两种同类信息不构成两因素。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q45','exam-fe','オブジェクト指向','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問45・改編】オブジェクト指向で、一般に「自動車」のサブクラスといえるものはどれか。','[{"id":"a","text":"エンジン"},{"id":"b","text":"製造番号"},{"id":"c","text":"タイヤ"},{"id":"d","text":"トラック"}]','"d"','トラックは自動車の一種であり、サブクラスのis-a関係を満たす。エンジンやタイヤは構成部品。 中文：卡车是一种汽车，符合继承关系；发动机和轮胎是组成部件。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q46','exam-fe','ホワイトボックステスト','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問46・改編】ホワイトボックステストの説明として適切なものはどれか。','[{"id":"a","text":"外部仕様に基づきテストデータを作成する"},{"id":"b","text":"同値分割を使いテストデータを作成する"},{"id":"c","text":"内部構造に基づきテストデータを作成する"},{"id":"d","text":"入力と出力の関係からテストデータを作成する"}]','"c"','内部構造や分岐を基に設計するのがホワイトボックステスト。 中文：白盒测试依据程序内部结构设计测试。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q48','exam-fe','テスト網羅','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問48・改編】単一の入り口をもち複数の判断を含むプログラムのテストにおける、命令網羅と判定条件網羅の関係はどれか。','[{"id":"a","text":"判定条件網羅を満たしても命令網羅を満たさない場合がある"},{"id":"b","text":"判定条件網羅を満たせば命令網羅も満たす"},{"id":"c","text":"命令網羅を満たさなくても判定条件網羅を満たす場合がある"},{"id":"d","text":"命令網羅を満たせば判定条件網羅も満たす"}]','"b"','この問題の判定条件網羅は各判定の真・偽の経路を通すため、到達可能な各命令を通る。命令網羅だけでは判定の両結果を通るとは限らない。 中文：题目中的判定分支覆盖包含各判定的真与假路径，可覆盖可达语句；语句覆盖不保证所有分支。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q49','exam-fe','リバースエンジニアリング','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問49・改編】プログラムからUMLのクラス図を生成することを何と呼ぶか。','[{"id":"a","text":"バックトラッキング"},{"id":"b","text":"フォワードエンジニアリング"},{"id":"c","text":"リエンジニアリング"},{"id":"d","text":"リバースエンジニアリング"}]','"d"','実装済みのコードから設計情報を復元するのはリバースエンジニアリング。 中文：从现有程序反向还原设计信息属于逆向工程。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption'),
('fe-exempt-2021-20210613-q50','exam-fe','構成管理','standard','single_choice','【IPA 2021年度 修了認定試験 2021-06-13 問50・改編】ソフトウェア開発で、構成管理に起因しない問題はどれか。','[{"id":"a","text":"定められた改版手続に従わずプログラムを修正し、既存機能が不正動作した"},{"id":"b","text":"システムテストで単体テストレベルのバグが多発し、開発が予定どおり進まない"},{"id":"c","text":"仕様書・設計書・プログラムの版数対応がなく、修正対象を特定しにくい"},{"id":"d","text":"派生元の修正が多数の派生プログラムすべてに反映されない"}]','"b"','単体テスト段階のバグが残る問題は主にテストや品質管理に関わる。版の対応や変更反映は構成管理の対象。 中文：单元测试级缺陷大量残留主要涉及测试质量；版本对应和变更传播属于配置管理。','licensed','https://www.ipa.go.jp/shiken/about/ug65p90000001bq0-att/tokurei_Mondai_20210613_FE.pdf','ja','A','explicit','standard','fe_exemption');
